/bin/zsh -lc "python3 -c 'import json
with open(\"input.json\") as f: data=json.load(f)
jobs={i:dict(id=i,state=\"PENDING\",attempt=0,lease_until=None) for i in data[\"jobs\"]}
tokens=set(); accepted=[]; rejected=[]
def expire(t):
 for j in jobs.values():
  if j[\"state\"]==\"RUNNING\" and j[\"lease_until\"]<=t: j.update(state=\"PENDING\",lease_until=None)
for e in sorted(data[\"events\"],key=lambda e:(e[\"time\"],e[\"sequence\"])):
 expire(e[\"time\"]); j=jobs[e[\"job\"]]; ok=False
 if e[\"kind\"]==\"START\" and j[\"state\"]==\"PENDING\":
  j.update(state=\"RUNNING\",attempt=j[\"attempt\"]+1,lease_until=e[\"time\"]+e[\"lease\"]); ok=True
 elif e[\"kind\"]==\"RESULT\" and j[\"state\"]==\"RUNNING\" and e[\"attempt\"]==j[\"attempt\"] and e[\"token\"] not in tokens:
  tokens.add(e[\"token\"]); j.update(state=\"DONE\",lease_until=None); ok=True
 elif e[\"kind\"]==\"CANCEL\" and j[\"state\"] not in (\"DONE\",\"CANCELLED\"):
  j.update(state=\"CANCELLED\",lease_until=None); ok=True
 (accepted if ok else rejected).append(e[\"sequence\"])
expire(data[\"horizon\"])
assert len(accepted)+len(rejected)==len(data[\"events\"])
print(json.dumps(dict(jobs=[jobs[i] for i in sorted(jobs)],accepted_sequences=accepted,rejected_sequences=rejected,accepted_tokens=sorted(tokens)),separators=(\",\",\":\")))'"

